/**
 * Contracts for the support chat API (`/v1/conversations`, `/v1/orders/lookup`).
 * Clients must ignore fields they don't know: the API adds optional fields
 * without bumping the version.
 */

export type SupportStoreCode = "uk" | "uae" | "intl" | "ca" | "usa" | "eu";

export interface SupportHealthResponse {
  status?: string;
  [key: string]: unknown;
}

export interface SupportConversation {
  /** 12 lowercase hex characters, generated by the server. */
  conversation_id: string;
  store: SupportStoreCode;
}

export interface SupportMessageRequest {
  store: SupportStoreCode;
  /** At most 2,000 characters. */
  message: string;
  /** The menu item `id` when the customer clicked a menu button. */
  menu_choice?: string | null;
}

export type SupportReplyType = "message" | "action" | "menu" | "input_request";

export type SupportRoute =
  | "product"
  | "knowledge"
  | "order_support"
  | "returns_claims"
  | "handoff"
  | "clarify";

export interface SupportIntent {
  label: string;
  confidence: number;
  /** `laya`, `menu`, `fallback` or `guard`. */
  source: string;
  probabilities?: Record<string, number>;
}

export interface SupportProduct {
  product_id: string;
  title: string;
  url: string;
  product_type?: string | null;
  /** A "from" price. */
  price_from: number | null;
  currency: string;
  available: boolean | null;
  image_url: string | null;
}

export interface SupportSource {
  title: string;
  url: string;
  source_type?: string | null;
}

export interface SupportHandoff {
  reference?: string | null;
  channel?: string | null;
}

export interface SupportAction {
  /** Today only `track_order`. Switch on it so new actions don't break clients. */
  name: string;
  order_number?: string | null;
}

export interface SupportMenuItem {
  id: string;
  label: string;
  description?: string | null;
  /** Shown as the customer's bubble and sent back with `menu_choice`. */
  message: string;
}

export interface SupportMenu {
  name: string;
  title?: string | null;
  items: SupportMenuItem[];
}

export interface SupportInputField {
  name: string;
  label?: string | null;
  type?: string | null;
  required?: boolean | null;
  placeholder?: string | null;
}

export type SupportInputOption = string | { value: string; label?: string | null };

export interface SupportInputRequest {
  /** `verify_order` or `confirm_action`. */
  kind: string;
  fields?: SupportInputField[] | null;
  options?: SupportInputOption[] | null;
}

export interface SupportReply {
  type: SupportReplyType;
  /** Always set. Plain text that may contain markdown links. */
  text: string;
  conversation_id?: string;
  intent?: SupportIntent | null;
  route?: SupportRoute | null;
  action?: SupportAction | null;
  menu?: SupportMenu | null;
  input?: SupportInputRequest | null;
  products?: SupportProduct[] | null;
  sources?: SupportSource[] | null;
  handoff?: SupportHandoff | null;
}

export type SupportToolOutcome =
  | "ok"
  | "failed"
  | "denied"
  | "invalid"
  | "planned"
  | "blocked"
  | "duplicate";

export type SupportStreamEvent =
  | { event: "start"; data: SupportConversation }
  | { event: "step"; data: { step: string; label: string } }
  | { event: "tool"; data: { tool: string; outcome: SupportToolOutcome } }
  | { event: "reply"; data: { reply: SupportReply } }
  | { event: "error"; data: SupportErrorBody };

export interface SupportPageEventRequest {
  store: SupportStoreCode;
  /** Lower case with underscores, e.g. `cart_add`, `product_viewed`. */
  type: string;
  /** At most 4,000 characters as JSON. Never card details or addresses. */
  data: Record<string, unknown>;
  summary?: string | null;
}

export interface SupportPageEvent {
  type: string;
  data: Record<string, unknown>;
  summary?: string | null;
  [key: string]: unknown;
}

export interface SupportPageEventsResponse {
  events: SupportPageEvent[];
}

export interface SupportOrderLookupRequest {
  store: SupportStoreCode;
  order_number: string;
  /** Send `email` or `postcode`; at least one is required. */
  email?: string | null;
  postcode?: string | null;
  conversation_id?: string | null;
}

export type SupportOrderStatus =
  | "not shipped yet"
  | "being prepared"
  | "on hold"
  | "partly shipped"
  | "shipped"
  | "delivered"
  | "cancelled";

export interface SupportMoney {
  amount: number;
  currency: string;
}

export interface SupportOrderItem {
  title: string;
  variant?: string | null;
  sku?: string | null;
  quantity: number;
}

export interface SupportOrder {
  order_number: string;
  placed: string | null;
  status: SupportOrderStatus | (string & {});
  delivered: string | null;
  payment_status?: string | null;
  fulfillment_status?: string | null;
  cancelled: boolean;
  total?: SupportMoney | null;
  items: SupportOrderItem[];
}

export interface SupportShipment {
  status?: string | null;
  shipped?: string | null;
  in_transit_since?: string | null;
  delivered?: string | null;
  estimated_delivery?: string | null;
  carrier?: string | null;
  tracking_numbers: string[];
  tracking_links: string[];
  items: { title: string; quantity: number }[];
  source?: string | null;
}

export interface SupportTracking {
  order_number: string;
  fulfillment_status?: string | null;
  shipments: SupportShipment[];
  note?: string | null;
}

/** A mismatch never says which detail was wrong. */
export type SupportOrderLookupResponse =
  | { verified: true; order: SupportOrder; tracking: SupportTracking | null }
  | { verified: false; order: null; tracking: null };

export type SupportErrorCode =
  | "invalid_request"
  | "conversation_not_found"
  | "not_found"
  | "method_not_allowed"
  | "conversation_busy"
  | "conversation_waiting"
  | "store_mismatch"
  | "rate_limited"
  | "upstream_unavailable"
  | "order_lookup_unavailable"
  | "internal_error";

export interface SupportErrorBody {
  error: {
    code: SupportErrorCode | (string & {});
    /** For developers and logs, never for customers. */
    message: string;
    request_id?: string;
    details?: { field: string; problem: string }[];
  };
}
